In this class, I have one dependency — IUserProfileRepository. You might already
suspect that the repository implementation for the UserProfile entity would be almost
the same as for ClassifiedAd, except that it will operate with another class type. You
might think that you can use a generic repository. But we have already touched upon this
topic, and you can either revisit it or read some articles on the internet that will invariably
discourage you from using generic repositories; however, we can still either use the generic
type as a dependency for our specific repository or we can inherit specific repositories from
a generic one. Let's try the latter option and see what it looks like. I will add a new class to

the Infrastructure folder for the application project, called RavenDbRepository, as
shown in the following code:
using System;
using System.Threading.Tasks;
using Marketplace.Framework;
using Raven.Client.Documents.Session;
namespace Marketplace.Infrastructure
{
public class RavenDbRepository<T, TId>
where T : AggregateRoot<TId>
where TId : Value<TId>
{
private readonly IAsyncDocumentSession _session;
private readonly Func<TId, string> _entityId;
CQRS - The Read Side Chapter 9
[ 269 ]
public RavenDbRepository(
IAsyncDocumentSession session,
Func<TId, string> entityId)
{
_session = session;
_entityId = entityId;
}
public Task Add(T entity)
=> _session.StoreAsync(entity, _entityId(entity.Id));
public Task<bool> Exists(TId id)
=> _session.Advanced.ExistsAsync(_entityId(id));
public Task<T> Load(TId id)
=> _session.LoadAsync<T>(_entityId(id));
}
}
