It is time to implement the API controller class. If you look at the
ClassifiedAdsCommandApi class, you can see that we have a private method called
HandleRequest that helps us to simplify the request handling by calling the application
service using one line of code. The code for the new controller will be almost identical, so
we can reuse the request handler by creating a new static class in the Infrastructure
folder called RequestHandler with the following simple code:
using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Serilog;
namespace Marketplace.Infrastructure
{
public static class RequestHandler
{
public static async Task<IActionResult> HandleRequest<T>(
T request, Func<T, Task> handler, ILogger log)
{
try
{
log.Debug("Handling HTTP request of type {type}",
typeof(T).Name);
await handler(request);
return new OkResult();
}
catch (Exception e)
{
log.Error(e, "Error handling the request");
return new BadRequestObjectResult(new {error =
e.Message, stackTrace = e.StackTrace});
}
}
}
}
